// ──────────────────────────────────────────────────────────────
// PREPARE OUTPUT
// ──────────────────────────────────────────────────────────────
// PURPOSE: Assemble the final Markdown document that will be
//          emailed AND saved to disk.
//
// INPUT comes from 'Merge Overview with Articles', which combined:
//   - port 0: Aggregate output → has .articles (array of all articles)
//   - port 1: Ollama Overview  → has .response (the overview text)
//   After merging, $json has BOTH .articles AND .response.
//
// OUTPUT: one item with everything needed downstream:
//   text/summaryText → the full Markdown (same value, two field names)
//   filename         → e.g. "news-summary-2025-05-01.md"
//   subject          → the email subject line
// ──────────────────────────────────────────────────────────────

const overviewResponse = $json.response || '';
const articles = $json.articles || [];

// Build today's date string (YYYY-MM-DD) for the filename and document header
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const date = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

// Build the '## Articles' section: one Markdown block per article,
// separated by horizontal rules (---)
const articlesSection = articles.map(a => {
  const dateLine = a.pubDate ? `\n*${a.pubDate}*` : '';
  return [
    `### ${a.title}`,
    `**Source:** ${a.source}${dateLine} | [Read more](${a.link || a.url})`,
    '',
    a.summary
  ].join('\n');
}).join('\n\n---\n\n');

// Stitch together the full Markdown document:
// header → AI overview → divider → all articles
const text = [
  `# Daily News Briefing — ${date}`,
  '',
  '## Overview',
  overviewResponse,
  '',
  '---',
  '',
  '## Articles',
  '',
  articlesSection
].join('\n');

return [{
  json: {
    text,
    summaryText: text,
    filename: `news-summary-${date}.md`,
    subject: `Daily News Summary - ${date}`,
    overview: overviewResponse,
    articles
  }
}];

// ──────────────────────────────────────────────────────────────
// ANSA PREPARE
// ──────────────────────────────────────────────────────────────
// PURPOSE: Shape the raw RSS items from ANSA into the standard
//          format expected by 'fn_add_articles()'.
//
// We add two fields:
//   source:   'ANSA'  → displayed in the final report
//   selector: CSS selector to find the article body on ANSA's site
//             (fn_add_articles will visit the URL and scrape this)
//
// 'mapped' tells fn_add_articles() which RSS field names to read
//   (some feeds use 'pubDate', others use 'isoDate' — we check both)
// 'required' filters out items that are missing critical fields
// ──────────────────────────────────────────────────────────────
return {
  articles: items.map(item => ({
    ...item.json,
    source: 'ANSA',
    selector: "div[itemprop='articleBody']"
  })), 

  required: ['title', 'link'],

  mapped: {
    title: 'title',
    link: 'link',
    pubDate: ['pubDate', 'isoDate'],
    snippet: ['contentSnippet', 'content']
  },
};

