// ──────────────────────────────────────────────────────────────
// AGGREGATE FOR OVERVIEW
// ──────────────────────────────────────────────────────────────
// PURPOSE: Collect ALL enriched articles and build the numbered
//          text block that Ollama will use to write the overview.
//
// THE BUG (now fixed): $input.all() would only return 1 article
// here — the last one the loop processed. That's because
// splitInBatches 'done' port only fires with the final item.
//
// THE FIX: We read from the static data scratchpad where
// 'Enrich with Summary' saved every article, one per iteration.
// ──────────────────────────────────────────────────────────────

// Read ALL accumulated articles from the global scratchpad
const staticData = $getWorkflowStaticData('global');
const articles = staticData.enrichedArticles || [];

// IMPORTANT: Reset the accumulator right now so the next
// scheduled run starts clean. Without this, articles from
// a previous run would bleed into the next one!
staticData.enrichedArticles = [];

// Build a numbered summary text for the Ollama overview prompt:
// "1. **Article Title** (Source)\nThe summary text..."
const summary = articles
  .map((a, i) => `${i + 1}. **${a.title}** (${a.source})\n${a.summary}`)
  .join('\n\n');

// Output ONE item with ALL articles + the combined summary.
// This single item flows into both 'Ollama Overview' (for the AI prompt)
// and 'Merge Overview with Articles' (to carry the articles array forward).
return [{ json: { articles, summary } }];

// ──────────────────────────────────────────────────────────────
// ARTICLE CHECKPOINT
// ──────────────────────────────────────────────────────────────
// PURPOSE: Save a snapshot of the article BEFORE sending it to Ollama.
//
// WHY: Ollama's response only contains { response: '...' }.
// It forgets everything else (title, source, link, pubDate...).
// By saving the full article here, 'Enrich with Summary' can
// retrieve it with: $('Article Checkpoint').item.json
//
// pairedItem: 0 tells n8n that this output maps to input item #0.
// ──────────────────────────────────────────────────────────────
return { json: $json, pairedItem: 0 };

// ──────────────────────────────────────────────────────────────
// ENRICH WITH SUMMARY
// ──────────────────────────────────────────────────────────────
// PURPOSE: Merge Ollama's AI summary back into the original
//          article data, then SAVE it to a persistent scratchpad.
//
// WHY A SCRATCHPAD? The loop (splitInBatches) processes ONE article
// at a time. When ALL articles are done, its 'done' output (port 1)
// only carries the LAST item — not all of them. So we manually
// accumulate every article using $getWorkflowStaticData('global').
// ──────────────────────────────────────────────────────────────

// $getWorkflowStaticData('global') = a sticky note that survives
// across all loop iterations within the same workflow run.
const staticData = $getWorkflowStaticData('global');

// Initialize the accumulator array on the very first article
if (!Array.isArray(staticData.enrichedArticles)) {
  staticData.enrichedArticles = [];
}

// Grab the original article fields saved by 'Article Checkpoint'
// (Ollama's response only has .response — we need title, link, etc.)
const original = $('Article Checkpoint').item.json;

// Build the enriched article: original data + AI-generated summary
const article = {
  ...original,
  summary: $json.response || ''
};

// Save this article to the accumulator so we can collect all of them later
staticData.enrichedArticles.push(article);

// Return the article so the loop can continue to the next iteration
return { json: article };
